package com.javaintro.copy;

public class PrimitiveDataTypes {
	
	byte age=21;
	short numberofstudents=72;
	int anuualsalary=50000;
	long population=1476625576L;
	float percentage=84.3F;
	double bankbalance=2432.34D;
	char grade='A';
	boolean javalearner=true;

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		PrimitiveDataTypes p1 = new PrimitiveDataTypes();
		System.out.println("Byte Value : " +p1.age);
		System.out.println("Short Value : " +p1.numberofstudents);
		System.out.println("Int Value : " +p1.anuualsalary);
		System.out.println("Long Value : " +p1.population);
		System.out.println("Float Value : " +p1.percentage);
		System.out.println("Double Value : " +p1.bankbalance);
		System.out.println("Char Value : " +p1.grade);
		System.out.println("Boolean Value : " +p1.javalearner);
		
	}

}
